public class LedgerRegistrationScene extends PixelScene{
 @Override public void create(){super.create();uiCamera.visible=false;Image book=LedgerEnvironment.addOpenBook(this);RectF l=LedgerEnvironment.leftPage(book),r=LedgerEnvironment.rightPage(book);float lx=l.left+7,lw=l.width()-14,rx=r.left+7,rw=r.width()-14,top=l.top+7;RenderedTextBlock h=t("遗迹下行者登记",8,LedgerEnvironment.INK,(int)lw);h.setPos(lx+(lw-h.width())/2f,top);add(h);Image hero=new Image(LedgerFlow.draft().heroClass.spritesheet(),0,90,12,15);hero.scale.set(1.7f);hero.x=lx+4;hero.y=h.bottom()+10;add(hero);float ix=hero.x+hero.width()+7;RenderedTextBlock il=t("理想职业",5,LedgerEnvironment.FADED_INK,(int)(l.right-ix-5));il.setPos(ix,hero.y);add(il);RenderedTextBlock iv=t(Messages.titleCase(LedgerFlow.draft().heroClass.title()),6,LedgerEnvironment.INK,(int)(l.right-ix-5));iv.setPos(ix,il.bottom()+2);add(iv);float y=Math.max(hero.y+hero.height(),iv.bottom())+12;RenderedTextBlock nl=t("姓名",5,LedgerEnvironment.FADED_INK,35);nl.setPos(lx+2,y);add(nl);String cur=LedgerFlow.draft().name;boolean unnamed=cur==null||cur.trim().isEmpty()||cur.equals("无名者");LedgerButton name=new LedgerButton(Chrome.Type.BLANK,unnamed?"点击写下姓名":cur,6){@Override protected void onClick(){super.onClick();String e=LedgerFlow.draft().name;LedgerRegistrationScene.this.add(new WndTextInput("登记姓名","写下当年进入遗迹前留下的名字。",e==null||e.equals("无名者")?"":e,20,false,"写入名册","取消"){@Override public void onSelect(boolean ok,String v){if(ok&&v!=null&&!v.trim().isEmpty()){LedgerFlow.draft().name=v.trim();Game.switchScene(LedgerRegistrationScene.class);}}});}};name.leftJustify=true;name.textColor(unnamed?LedgerEnvironment.FADED_INK:LedgerEnvironment.INK);name.setRect(lx+37,y-5,lw-39,17);add(name);y+=25;RenderedTextBlock dl=t("去向",5,LedgerEnvironment.FADED_INK,35);dl.setPos(lx+2,y);add(dl);RenderedTextBlock dv=t("地下遗迹",6,LedgerEnvironment.INK,(int)lw-42);dv.setPos(lx+39,y);add(dv);RenderedTextBlock sm=t("本人于下行前登记。",5,LedgerEnvironment.FADED_INK,(int)lw-4);sm.setPos(lx+2,Math.min(l.bottom-30,y+31));add(sm);RenderedTextBlock rh=t("登记说明",8,LedgerEnvironment.INK,(int)rw);rh.setPos(rx+(rw-rh.width())/2f,top);add(rh);RenderedTextBlock note=t("这本名册只写下出发前\n能够知道的事情。\n\n姓名\n理想职业\n惯用兵器\n去向\n\n后来发生的事，\n不属于这一页。",5,LedgerEnvironment.FADED_INK,(int)rw-6);note.setPos(rx+3,rh.bottom()+11);add(note);LedgerButton next=new LedgerButton(Chrome.Type.BLANK,"继续填写惯用兵器  ›",6){@Override protected void onClick(){super.onClick();String n=LedgerFlow.draft().name;if(n==null||n.trim().isEmpty()||n.equals("无名者")){LedgerRegistrationScene.this.add(new WndMessage("先在名册上留下一个名字。"));return;}Game.switchScene(LedgerWeaponScene.class);}};next.textColor(LedgerEnvironment.INK);next.setRect(rx,r.bottom-20,rw,15);add(next);LedgerButton back=new LedgerButton(Chrome.Type.BLANK,"‹ 重新选择身份",5){@Override protected void onClick(){super.onClick();Game.switchScene(LedgerHeroScene.class);}};back.textColor(LedgerEnvironment.FADED_INK);back.setRect(lx,l.bottom-20,lw,15);add(back);fadeIn();}
 private RenderedTextBlock t(String v,int s,int c,int w){RenderedTextBlock b=new RenderedTextBlock(v,s,false);b.maxWidth(w);b.hardlight(c);return b;}
}
